package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamWesternClassicBank1 {
    private const val T = "බටහිර සම්භාව්‍ය කලාව (මිසර, ග්‍රීක, රෝම, පුනරුද, බැරොක්)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පැරණි මිසර (ඊජිප්තු) චිත්‍ර කලාවේ මිනිස් රූප ඇඳීමේදී අනුගමනය කළ සම්මත නීතිය කුමක්ද?", "ප්‍රධාන භාගික දෘෂ්ටිය", "ත්‍රිමාණ පර්යාලෝක දෘෂ්ටිය", "පසුබිම් නොමැති රේඛා ක්‍රමය", "වියුක්ත ජ්‍යාමිතික රටා ක්‍රමය", "සිරුරේ සෑම කොටසක්ම වඩාත් පැහැදිලිව පෙනෙන කෝණයෙන් එකම රූපයට එක් කිරීම මිසර රීතියයි."),
        q("මිසර කලාවේ විශිෂ්ටත්වය පෙන්වන 'ගීසා හි මහා පිරමීඩ' සහ 'ස්පින්ක්ස්' ප්‍රතිමාව ඉදි කළේ කුමන අරමුණකින්ද?", "රජවරුන්ගේ මතු ජීවිත ආරක්ෂාව", "නගර වෙළඳපොළ හා රංග පීඨ", "පොදු ජල සැපයුම් ස්ථාන", "තාරකා නිරීක්ෂණාගාර ලෙස", "මිසර කලාව සදාකාලික මරණින් මතු පැවැත්ම (Ka) පිළිබඳ විශ්වාසය මත ගොඩනැගුණි."),
        q("මිසරයේ අමර්ණ යුගයට (Amarna Period) අයත් තුත්මෝස් මූර්ති ශිල්පියා විසින් නිර්මාණය කළ සුප්‍රකට ආලේඛ්‍ය ප්‍රතිමාව කුමක්ද?", "නෙෆර්ටිටි රැජිනගේ උඩුකය", "මොනාලිසා ආලේඛ්‍ය සිතුවම", "වීනස් ඩි මිලෝ ප්‍රතිමාව", "ඩේවිඩ් කිරිගරුඬ ප්‍රතිමාව", "වර්ණ ගැන්වූ හුණුගලින් තැනූ නෙෆර්ටිටි රැජිනගේ ප්‍රතිමාව බර්ලින් කෞතුකාගාරයේ සුරැකිව ඇත."),
        q("මිසර පාරාවෝ රජවරුන් අතර මුළුමනින්ම පාහේ නොබිඳී හමුවූ සොහොන් ගැබ සහ එහි තිබූ ඝන රන් වෙස්මුහුණ අයත් වන්නේ කාටද?", "තූතන්කාමන් රජුට (Tutankhamun)", "මහා ඇලෙක්සැන්ඩර් රජුට", "ජූලියස් සීසර්ට", "කාශ්‍යප රජුට", "1922 දී හොවාර්ඩ් කාටර් සොයාගත් තූතන්කාමන් සොහොන් ගැබේ රන් වෙස්මුහුණ ලොව ප්‍රකටය."),
        q("මිසර චිත්‍ර කලාවේ පාරාවෝ රජු සේවකයන්ට හා සතුරන්ට වඩා ඉතා විශාලව ඇඳීමෙන් පෙන්වන්නේ කුමක්ද?", "සමාජ තත්ත්වයේ උසස් බව", "රජුගේ ශාරීරික යෝධ බව", "ඒකලක්ෂ්‍ය රේඛීය දෘෂ්ටිය", "වායුගෝලීය අවකාශ ගැඹුර", "චරිතයේ බලය හා වැදගත්කම ප්‍රමාණයෙන් දැක්වීම මිසර කලාවේ සම්මත නියමයකි."),
        q("මිසර බිතුසිතුවම්වල ගැහැනු හා පිරිමි රූප වෙන්කර හඳුනා ගැනීමට යොදාගත් සාම්ප්‍රදායික සමේ වර්ණ මොනවාද?", "පිරිමින් රතු-දුඹුරු පැහැයෙන් හා කාන්තාවන් ලා කහ පැහැයෙන්", "පිරිමින් නිල් හා කාන්තාවන් කොළ පැහැයෙන්", "දෙපිරිසම තනි කළු පැහැයෙන්", "කාන්තාවන් අඳුරු දම් පැහැයෙන්", "මිසර ශිල්පීන් පිරිමින්ට රතු ගුරුගල් පැහැයද කාන්තාවන්ට සෞම්‍ය කහ පැහැයද යොදා ගත්හ."),
        q("පුරාණ ග්‍රීක මූර්ති කලාවේ සම්භාව්‍ය යුගයේ (Classical Period) කැපී පෙනෙන ප්‍රධාන ලක්ෂණය කුමක්ද?", "මානව සිරුරේ පරිපූර්ණ අනුපාත, කායව්‍යවච්ඡේදය හා චලන සමතුලිතතාව", "මිනිස් රූප කූරු මෙන් ඇඳීම", "විකෘති වූ මුහුණු නෙළීම", "හතරැස් කුට්ටි මත කෙටුම් කිරීම", "ග්‍රීක කලාව මිනිසා සියලු දේවල මිනුම් දණ්ඩ ලෙස සලකා පරිපූර්ණ සිරුරු නෙළීය."),
        q("සම්භාව්‍ය ග්‍රීක මූර්තිවල දණහිස මදක් නවා එක් පාදයකට බර දී උරහිස හා ඉඟ ප්‍රතිවිරුද්ධව ඇල කර සිටගැනීමේ ස්වභාවික ඉරියව්ව කුමක්ද?", "කොන්ට්‍රපොස්ටෝ (Contrapposto)", "ත්‍රිභංග පද්මාසනය", "ප්‍රොෆයිල් රීතිය", "ක්‍යාරොස්කුරෝ", "පොලික්ලයිටස්ගේ ඩොරිෆොරස් හා මයිකල් ආන්ජලෝගේ ඩේවිඩ් ප්‍රතිමාවල මෙම සජීවී ඉරියව්ව දැකිය හැකිය."),
        q("ග්‍රීක සම්භාව්‍ය මූර්ති ශිල්පී 'මයිරන්' (Myron) විසින් නිර්මාණය කරන ලද ලෝක ප්‍රකට ක්‍රීඩා ප්‍රතිමාව කුමක්ද?", "කවපෙත්ත විසි කරන්නා", "රොඩින්ගේ චින්තකයා", "වීනස් ඩි මිලෝ ප්‍රතිමාව", "මයිකල් ආන්ජලෝගේ පීටා", "ක්‍රීඩකයාගේ උපරිම චලනය හා ආතතිය එක් මොහොතක රඳවා ගත් ලෝකඩ (පසුව කිරිගරුඬ) ප්‍රතිමාවකි."),
        q("ග්‍රීසියේ ඇතන්ස් නුවර ඇක්‍රොපොලිස් කඳු මුදුනේ ඇතීනා දේවතාවිය වෙනුවෙන් ඉදි කළ සම්භාව්‍ය ගොඩනැගිල්ල කුමක්ද?", "පාතිනන් දේවාලය (Parthenon)", "කොලෝසියම", "පැන්තියන් දේවාලය", "ටජ් මහල්", "ඉක්ටිනස් හා කැලික්‍රේටීස් නිර්මාණය කළ පාතිනන් දේවාලය ඩොරික් ගෘහ නිර්මාණයේ පරමාදර්ශයයි."),
        q("පුරාණ ග්‍රීක ගෘහ නිර්මාණයේ ප්‍රධාන කුළුණු ශෛලි (Greek Orders) තුන පිළිවෙළින් සරල සිට අලංකාර දක්වා කවරේද?", "ඩොරික්, අයනික සහ කොරින්තියානු (Doric, Ionic, Corinthian)", "නාගර, ද්‍රවිඩ සහ වේසර", "ගොතික්, බැරොක් සහ රොකොකෝ", "මෞර්ය, ගුප්ත සහ චෝල", "ඩොරික් සරල හිසින්ද, අයනික දඟර යුගලයකින්ද, කොරින්තියානු ඇකැන්තස් පත්‍රවලින්ද යුක්තය."),
        q("හෙලනිස්තික ග්‍රීක යුගයට (Hellenistic Period) අයත් පියාපත් සහිත විජයග්‍රහණයේ දේවතාවිය දක්වන ප්‍රතිමාව කුමක්ද?", "සමොත්‍රේස් හි නයිකි", "නෙෆර්ටිටි උඩුකය", "තරුණ කූරෝස් ප්‍රතිමාව", "ෆ්ලෝරන්ස් ඩේවිඩ්", "සුළඟට ලෙළදෙන වස්ත්‍රය හා නාට්‍යමය චලනය හෙලනිස්තික කලාවේ ප්‍රබල හැඟීම් ප්‍රකාශනය පෙන්වයි."),
        q("ග්‍රීක බඳුන් චිත්‍ර කලාවේ (Greek Vase Painting) ප්‍රධාන වශයෙන් ජනප්‍රිය වූ ශෛලීන් දෙක මොනවාද?", "කළු-රූප සහ රතු-රූප ශෛලීන්", "නිල්-සුදු සහ සෙලඩොන්", "ගුරුගල් සහ ගොකටු කහ", "මොසැයික් සහ කොලාජ් ක්‍රම", "මැටි බඳුන් මත මිථ්‍යා කතා හා ක්‍රීඩා දර්ශන කළු හෝ රතු පැහැයෙන් සියුම්ව ඇඳ පිළිස්සීය."),
        q("පුරාණ රෝම ගෘහ නිර්මාණ ශිල්පීන් ග්‍රීක කුළුණුවලට අමතරව විශාල ගොඩනැගිලි තැනීමට විප්ලවීය ලෙස භාවිත කළ අංග මොනවාද?", "ආරුක්කුව, ගෝලාකාර වහල හා කොන්ක්‍රීට්", "දැව පේකඩ සහ පොල් අතු වහල", "අමු මැටි සහ පිදුරු බිත්ති", "පියාඹන ආධාරක සහ උල් ආරුක්කු", "ආරුක්කු, වෝල්ට් හා කොන්ක්‍රීට් භාවිතය නිසා කොලෝසියම හා පැන්තියන් වැනි දැවැන්ත ශාලා බිහිවිය."),
        q("රෝම අධිරාජ්‍යයේ ඉංජිනේරු හා වාස්තු කලා කුසලතාව විදහා දක්වන රෝමයේ පිහිටි යෝධ රංග පීඨය කුමක්ද?", "කොලෝසියම (Colosseum)", "පාතිනන් දේවාලය", "සාංචි ස්තූපය", "නොට්‍ර-ඩෑම් දෙව්මැදුර", "කොලෝසියමේ පිටත බිත්තිවල පහළ සිට ඉහළට ඩොරික්, අයනික හා කොරින්තියානු ආරුක්කු මහල් දක්නට ඇත."),
        q("රෝමයේ 'පොම්පේයි' (Pompeii) නගරයේ ගිනිකඳු අළුවලින් සුරැකුණු බිතුසිතුවම්වල දැකිය හැකි විශේෂත්වය කුමක්ද?", "ත්‍රිමාණ ගැඹුර මවන මායා සිතුවම්", "වියුක්ත ජ්‍යාමිතික රේඛා රටා", "තනි කළු-සුදු සමෝච්ඡ රූප", "ප්‍රාග් ඓතිහාසික සත්ව රූප", "ගැඹුර, සෙවණැලි හා දෘශ්‍ය රැවටීම් (Illusionism) රෝම බිතුසිතුවම්වල ඉතා දියුණු මට්ටමක තිබුණි."),
        q("මධ්‍යකාලීන යුරෝපයේ 'බයිසැන්ටයින්' (Byzantine) කලාවේ ඉතාම ප්‍රකට අලංකරණ කලා මාධ්‍යය කුමක්ද?", "රන් පසුබිම් මොසැයික් කලාව", "ජපන් උකියෝ-ඒ ලී මුද්‍රණ", "සාම්ප්‍රදායික ඉටි බතික්", "කැන්වස් මත ඇක්‍රිලික්", "හගියා සොෆියා හා රවේනා පල්ලිවල දිලිසෙන වීදුරු මොසැයික් චිත්‍ර බයිසැන්ටයින් කලාවේ හදවතයි."),
        q("මධ්‍යකාලීන 'ගොතික්' (Gothic) ආසන දෙව්මැදුරු ගෘහ නිර්මාණයේ ප්‍රධාන වාස්තු ලක්ෂණ තුන මොනවාද?", "උල් ආරුක්කු, පියාඹන ආධාරක, වීදුරු ජනෙල්", "පිරමීඩ, ස්පින්ක්ස් හා කුළුණු පෙළ", "පැතලි දැව වහල හා මැටි බිත්ති", "ඩොරික් කුළුණු හා රවුම් ආරුක්කු", "බිත්තිවල බර පිටතට යොමු කිරීම නිසා ඉතා උස් වීදුරු ජනෙල් සහිත ආලෝකවත් දෙව්මැදුරු තැනීය."),
        q("14 වන සියවසේ ඉතාලියේ පුනරුද කලාවට පදනම දැමූ 'ජොටෝ ඩි බොන්ඩෝනේ' (Giotto) හඳුන්වන්නේ ඇයි?", "ත්‍රිමාණ බර හා හැඟීම් නැවත ගෙන ඒම නිසා", "පළමු ඡායාරූප කැමරාව නිපදවීම නිසා", "තෙල් සායම් සම්පූර්ණයෙන් තහනම් කිරීම නිසා", "ග්‍රීක පාතිනන් දේවාලය ගොඩනැගීම නිසා", "අරේනා දෙව්මැදුරේ ජොටෝ ඇඳි ෆ්‍රෙස්කෝ සිතුවම් බටහිර චිත්‍ර කලාවේ පුනරුද පෙරගමන්කරුවා විය."),
        q("15–16 සියවස්වල ඉතාලියේ ඇති වූ 'පුනරුදය' (Renaissance) යන වචනයේ සෘජු අර්ථය කුමක්ද?", "සම්භාව්‍ය කලාව නැවත ඉපදීම", "රෝම කලාව සම්පූර්ණ විනාශය", "මධ්‍යකාලීන අන්ධකාර යුගය", "කාර්මික යන්ත්‍ර විප්ලවය", "ෆ්ලෝරන්ස් නගරයෙන් ඇරඹි පුනරුදය මානවවාදය, විද්‍යාව හා සම්භාව්‍ය කලාව නැවත ඉපදවීය."),
        q("පුනරුද යුගයේ චිත්‍ර කලාවට විප්ලවීය වෙනසක් ගෙන ආ 'රේඛීය දෘෂ්ටිකෝණය' (Linear Perspective) විද්‍යාත්මකව සොයා ගත්තේ කවුද?", "ෆිලිප්පෝ බෘනෙලෙස්කි", "වින්සන්ට් වෑන් ගෝ", "එඩ්ගා ඩෙගාස්", "පැබ්ලෝ පිකාසෝ", "ෆ්ලෝරන්ස් දෙව්මැදුරේ ගෝලාකාර වහල තැනූ බෘනෙලෙස්කි ක්ෂිතිජ රේඛාව හා අභිසාරී ලක්ෂ්‍ය නියමය සොයා ගත්තේය."),
        q("පුනරුද චිත්‍ර කලාවේ ප්‍රධාන තිදෙනා (High Renaissance Masters) ලෙස සැලකෙන ශ්‍රේෂ්ඨ කලාකරුවන් තිදෙනා කවුද?", "ලියනාඩෝ ඩා වින්චි, මයිකල් ආන්ජලෝ සහ රැෆායෙල්", "මොනේ, රෙනෝයා සහ ඩෙගාස්", "පිකාසෝ, බ්‍රාක් සහ මැටිස්", "හොකුසායි, හිරෝෂිගේ සහ උටමාරෝ", "15–16 සියවස්වල ඉතාලියේ මහා පුනරුදය ඔසවා තැබුවේ මෙම අසමසම ත්‍රිත්වයයි."),
        q("ලියනාඩෝ ඩා වින්චි විසින් නිර්මාණය කළ ලොව වඩාත්ම ප්‍රසිද්ධ ආලේඛ්‍ය සිතුවම කුමක්ද?", "මොනාලිසා (Mona Lisa)", "තාරකා රාත්‍රිය", "ගුවර්නිකා", "රාත්‍රී මුරය", "පැරීසියේ ලූවර් කෞතුකාගාරයේ ඇති මොනාලිසා සිතුවම ඇගේ අභිරහස් සිනහව හා මෘදු සෙවණැලි නිසා ප්‍රකටය."),
        q("ලියනාඩෝ ඩා වින්චි මොනාලිසා සිතුවමේ මායිම් දැඩි රේඛාවලින් තොරව දුමක් මෙන් මෘදුව මුසු කිරීමට භාවිත කළ ශිල්පය කුමක්ද?", "ස්ෆුමාටෝ (Sfumato)", "ඉම්පැස්ටෝ", "පොයින්ටිලිසම්", "කොලාජ්", "ඉතාලි බසින් 'දුම මෙන්' යන අරුතැති ස්ෆුමාටෝ ක්‍රමයෙන් තීන්ත ස්තර කිහිපයකින් මෘදු සෙවණැලි මැවීය."),
        q("ලියනාඩෝ ඩා වින්චිගේ 'අවසන් රාත්‍රී භෝජනය' (The Last Supper) සිතුවමේ දැකිය හැකි ප්‍රබල සංයුතික උපක්‍රමය කුමක්ද?", "සියලු දෘෂ්ටිකෝණ අභිසාරී රේඛා ක්‍රිස්තුස් වහන්සේගේ හිස පිටුපස කේන්ද්‍රගත වීම", "තනි රතු පසුබිමක කහ රූප ඇඳීම", "වියුක්ත කොටු තුළ චරිත සැඟවීම", "හිස් අවකාශය ඉතිරි කර තැබීම", "මිලාන් නුවර ශාලා බිත්තියක ඇඳි මෙම සිතුවම රේඛීය දෘෂ්ටිකෝණය හා නාට්‍යමය ප්‍රකාශනය මනාව පෙන්වයි."),
        q("මයිකල් ආන්ජලෝ විසින් තනි සුදු කැරාරා කිරිගරුඬ කුට්ටියකින් නෙළන ලද මීටර් 5 කට වඩා උස විශිෂ්ට මූර්තිය කුමක්ද?", "ඩේවිඩ් ප්‍රතිමාව (David)", "චින්තකයා (The Thinker)", "නෙෆර්ටිටි", "ලැකූන් ප්‍රතිමාව", "ෆ්ලෝරන්ස් නුවර තබා ඇති ඩේවිඩ් ප්‍රතිමාව තරුණ ශක්තිය හා කායව්‍යවච්ඡේද සුන්දරත්වයේ මුදුන් මල්කඩයි."),
        q("වතිකානුවේ ශාන්ත පීතර බැසිලිකාවේ ඇති මයිකල් ආන්ජලෝගේ 'පීටා' (Pietà) කිරිගරුඬ මූර්තියේ නිරූපණය කර ඇත්තේ කුමක්ද?", "මරියතුමිය උකුළේ ක්‍රිස්තු දේහය", "රාජ සභාවක යුද ජයග්‍රහණය", "මලල ක්‍රීඩකයෙකු දුවන රුව", "පාරාවෝ රජෙකුගේ ඔටුනු පැළඳීම", "වයස 24දී නෙළූ මෙම මූර්තියේ වස්ත්‍ර රැලි හා මෘදු හැඟීම් ප්‍රකාශනය අතිශය විස්මයජනකය."),
        q("වතිකානුවේ 'සිස්ටීන් දෙව්මැදුරේ' (Sistine Chapel) සිවිලිමේ ඇති ලෝක ප්‍රසිද්ධ බයිබල් ෆ්‍රෙස්කෝ සිතුවම් මාලාව නිර්මාණය කළේ කවුද?", "මයිකල් ආන්ජලෝ (Michelangelo)", "ලියනාඩෝ ඩා වින්චි", "ක්ලෝඩ් මොනේ", "පැබ්ලෝ පිකාසෝ", "වසර හතරක් පුරා මයිකල් ආන්ජලෝ 'ආදම් මැවීම' ඇතුළු සිස්ටීන් දෙව්මැදුරු සිවිලිම සිතුවම් කළේය."),
        q("රැෆායෙල් සන්සියෝ (Raphael) විසින් වතිකානුවේ ඇඳි පුරාණ ග්‍රීක දාර්ශනිකයන් පිරිවරා ගත් ෆ්‍රෙස්කෝ සිතුවම කුමක්ද?", "ඇතන්ස් පාසල (The School of Athens)", "මොනාලිසා", "ගුවර්නිකා", "වසන්තය", "ප්ලේටෝ හා ඇරිස්ටෝටල් මධ්‍යයේ තබා පුනරුද යුගයේ සමතුලිතතාව හා දෘෂ්ටිකෝණය මෙහි පෙන්වා ඇත."),
        q("සැන්ඩ්‍රෝ බොටිචෙලි (Sandro Botticelli) විසින් නිර්මාණය කළ 'වීනස්ගේ උපත' (The Birth of Venus) සිතුවම ප්‍රකට වන්නේ කුමන ලක්ෂණය නිසාද?", "ලයාන්විත රේඛා හා ග්‍රීක පුරාණෝක්ති", "තද කළු-සුදු සෙවණැලි ප්‍රතිවිරෝධතාව", "ත්‍රිමාණ කියුබිස්ට් ජ්‍යාමිතික හැඩතල", "වියුක්ත පැල්ලම් සහ රළු තීන්ත ස්තර", "මුල් පුනරුද යුගයේ ෆ්ලෝරන්ස් නුවර බිහි වූ මෙම කෘතිය චලන ලාලිත්‍යයේ අග්‍රගණ්‍ය උදාහරණයකි."),
        q("චිත්‍ර කලාවේදී 'තෙත් හුණු බදාමය' මත බදාමය වියළීමට පෙර ජලයේ දියකළ වර්ණවලින් ඇඳීමේ ස්ථිර බිතුසිතුවම් ශිල්පය කුමක්ද?", "ෆ්‍රෙස්කෝ බුඕනෝ (Fresco Buon)", "කැන්වස් මත තෙල් සායම්", "කඩදාසි මත ජල සායම්", "පැස්ටල් හා අඟුරු සිතුවම්", "වර්ණ කුඩු තෙත් හුණු සමඟ රසායනිකව බැඳෙන නිසා පුනරුද ෆ්‍රෙස්කෝ සිතුවම් සියවස් ගණනක් පවතී."),
        q("උතුරු යුරෝපීය පුනරුදයේදී තෙල් සායම් (Oil Painting) තාක්ෂණය ඉහළම සියුම් මට්ටමකට දියුණු කළ නෙදර්ලන්ත ශිල්පියා කවුද?", "ජෑන් වෑන් අයික් (Jan van Eyck)", "ජොටෝ", "මයිරන්", "ඇන්ඩි වෝහෝල්", "'ආනොල්ෆිනි විවාහ ආලේඛ්‍යය' වැනි කෘති හරහා වෑන් අයික් විනිවිද පෙනෙන තෙල් සායම් ස්තර (Glazing) හඳුන්වා දුන්නේය."),
        q("17 වන සියවසේ යුරෝපයේ පැවති 'බැරොක්' (Baroque) කලා ශෛලියේ ප්‍රධාන ලක්ෂණ මොනවාද?", "නාට්‍යමය චලනය හා තීව්‍ර ආලෝක-අඳුර", "නිසල සමමිතික සිරස් රේඛා පමණක්", "වර්ණ රහිත පැතලි ද්විමාන රූප", "සරල ජ්‍යාමිතික කොටු රටා පමණක්", "පුනරුදයේ ශාන්ත සමතුලිතතාව ඉක්මවා නාට්‍යමය උද්වේගය හා ගතික බව බැරොක් කලාවට එක් විය."),
        q("බැරොක් චිත්‍ර කලාවේ ආලෝකය හා තද අඳුර අතර ඇති අතිශය තියුණු ප්‍රතිවිරෝධතාව (Dramatic Dark-Light Contrast) හඳුන්වන්නේ කුමන නමින්ද?", "ටෙනෙබ්‍රිසම් හෙවත් ක්යාරොස්කුරෝ", "ස්ෆුමාටෝ මෘදු මිශ්‍රණය", "පොයින්ටිලිසම් තිත් ක්‍රමය", "ෆෝවිසම් වර්ණ භාවිතය", "කැරවැජියෝ සහ රෙම්බ්‍රාන්ට් අඳුරු පසුබිමකින් චරිත මතට තියුණු ආලෝකයක් එල්ල කර ගැඹුර මැවූහ."),
        q("තද අඳුරු පසුබිම් හා සාමාන්‍ය ජනයා යොදා ගෙන බයිබල් කතා යථාර්ථවාදීව ඇඳි ප්‍රකට ඉතාලි බැරොක් ශිල්පියා කවුද?", "කැරවැජියෝ (Caravaggio)", "බොටිචෙලි", "ෆ්‍රා ඇන්ජලිකෝ", "පෝල් ක්ලී", "'ශාන්ත මැතිව් කැඳවීම' වැනි කෘතිවලින් කැරවැජියෝ නාට්‍යමය ආලෝක ශිල්පය යුරෝපය පුරා ප්‍රචලිත කළේය."),
        q("බැරොක් යුගයේ සිටි විශිෂ්ට ලන්දේසි චිත්‍ර ශිල්පියෙකු වන රෙම්බ්‍රාන්ට් වෑන් රිජ්න්ගේ (Rembrandt) ලෝක ප්‍රසිද්ධ සමූහ ආලේඛ්‍ය චිත්‍රය කුමක්ද?", "රාත්‍රී මුරය (The Night Watch)", "මොනාලිසා", "රන් හිරු උදාව", "තාරකා රාත්‍රිය", "ආලෝක-අඳුර, චලනය හා ආත්ම ආලේඛ්‍ය සිතුවම් සඳහා රෙම්බ්‍රාන්ට් අතිශය ප්‍රකටය."),
        q("දෛනික ගෘහ ජීවිතයේ සාමකාමී අවස්ථා හා ජනේලයෙන් එන ස්වභාවික ආලෝකය සිතුවම් කළ 'මුතු කරාබු පැළඳි යුවතිය' නිර්මාණය කළ ලන්දේසි ශිල්පියා කවුද?", "ජොහැන්නස් වර්මීර්", "පීටර් පෝල් රූබන්ස්", "ඩියේගෝ වෙලාස්කුවෙස්", "එඩ්ගා ඩෙගාස්", "වර්මීර් නිල් සහ කහ වර්ණ හා මෘදු දිවා ආලෝකය ඉතා සියුම්ව භාවිත කළ බැරොක් යුගයේ ශිල්පියෙකි."),
        q("ඉතාලි බැරොක් මූර්ති කලාවේ විශිෂ්ටයා වූ 'ජියන් ලොරෙන්සෝ බර්නිනි' (Bernini) නෙළූ ඩේවිඩ් ප්‍රතිමාව මයිකල් ආන්ජලෝගේ ඩේවිඩ්ගෙන් වෙනස් වන්නේ කෙසේද?", "බර්නිනිගේ ඩේවිඩ් ගල් පටිය කරකවන උපරිම චලන මොහොත නිරූපණය කරයි", "බර්නිනි එය මැටියෙන් තැනීය", "මයිකල් ආන්ජලෝගේ ප්‍රතිමාව නටන ඉරියව්වකින් යුක්තය", "බර්නිනි ඩේවිඩ් වෙනුවට ගොලියත් පමණක් නෙළීය", "සන්සුන් සූදානම වෙනුවට ක්‍රියාත්මක වන තීරණාත්මක චලනය දැක්වීම බැරොක් මූර්ති ලක්ෂණයකි."),
        q("ස්පාඤ්ඤ රාජ සභාවේ ප්‍රධාන බැරොක් චිත්‍ර ශිල්පියා වූ 'ඩියේගෝ වෙලාස්කුවෙස්' (Velázquez) ඇඳි ලෝක ප්‍රකට සංකීර්ණ සිතුවම කුමක්ද?", "ලාස් මෙනිනාස් (Las Meninas)", "මොනාලිසා ආලේඛ්‍යය", "ගුවර්නිකා සිතුවම", "ඇතන්ස් පාසල චිත්‍රය", "කැඩපත හා බැල්ම උපයෝගී කර ගනිමින් නරඹන්නාත් සිතුවමේ කොටසක් බවට පත් කරන අද්විතීය කෘතියකි."),
        q("18 වන සියවසේ ප්‍රංශ රාජ සභාව තුළ ප්‍රචලිත වූ අතිශය අලංකාර, ලා වර්ණ හා සැහැල්ලු ප්‍රේමණීය බව දැක්වෙන කලා ශෛලිය කුමක්ද?", "රොකොකෝ (Rococo)", "ගොතික්", "ඩොරික්", "කියුබිසම්", "ෆ්‍රගොනාඩ් හා වෝටෝ වැනි ශිල්පීන් රොකොකෝ සැරසිලි හා ප්‍රසන්න උද්‍යාන දර්ශන සිතුවම් කළහ."),
        q("18 වන සියවස අගදී රොකොකෝ ශෛලියට එරෙහිව පැරණි ග්‍රීක-රෝම විනය, සදාචාරය හා සමබරතාව නැවත ගෙන ආ කලා ව්‍යාපාරය කුමක්ද?", "නව-සම්භාව්‍යවාදය (Neoclassicism)", "අධියථාර්ථවාදය", "පොප් කලාව", "ප්‍රාග් ඓතිහාසික කලාව", "ප්‍රංශ විප්ලව සමයේ ජැක්-ලුවී ඩේවිඩ් නව-සම්භාව්‍යවාදී චිත්‍ර හරහා වීරත්වය හා පැහැදිලි රේඛා මතු කළේය."),
        q("'සොක්‍රටීස්ගේ මරණය' හා 'හොරාටිවරුන්ගේ දිවුරුම' නිර්මාණය කළ ප්‍රංශ නව-සම්භාව්‍යවාදී චිත්‍ර ශිල්පියා කවුද?", "ජැක්-ලුවී ඩේවිඩ්", "ඉයුජින් ඩෙලාක්‍රොයික්ස්", "සැල්වදෝර් ඩාලි", "ක්ලෝඩ් මොනේ", "තියුණු බාහිර රේඛා, සම්භාව්‍ය ඇඳුම් හා දැඩි දේශපාලනික-සදාචාර පණිවිඩ ඩේවිඩ්ගේ චිත්‍රවල දැකිය හැකිය."),
        q("19 වන සියවසේ මුල් භාගයේදී තර්කයට වඩා මානව හැඟීම්, සොබාදහමේ බියකරු ශක්තිය හා නිදහස අගය කළ කලා ව්‍යාපාරය කුමක්ද?", "රොමෑන්ටික්වාදය (Romanticism)", "නව-සම්භාව්‍යවාදය", "බයිසැන්ටයින් කලාව", "නිර්මාණවාදය", "ඩෙලාක්‍රොයික්ස්, ගොයා, ටර්නර් හා ජෙරිකෝ රොමෑන්ටික් චිත්‍ර හරහා ප්‍රබල චිත්තවේග මතු කළහ."),
        q("ප්‍රංශ විප්ලවීය ජීවගුණය විදහා දක්වන 'ජනතාවට මග පෙන්වන නිදහස' (Liberty Leading the People) සිතුවම ඇන්ද රොමෑන්ටික් ශිල්පියා කවුද?", "ඉයුජින් ඩෙලාක්‍රොයික්ස්", "ජැක්-ලුවී ඩේවිඩ්", "රැෆායෙල් සන්සියෝ", "ෆ්‍රැන්සිස්කෝ ගොයා", "ත්‍රිකෝණාකාර සංයුතියක් හා උණුසුම් ගිනිගන්නාසුලු වර්ණ භාවිතය ඩෙලාක්‍රොයික්ස්ගේ විශේෂත්වයයි."),
        q("මුහුදු කුණාටු, මීදුම හා ආලෝකයේ බලවත්කම චිත්‍රයට නගමින් පසුකාලීන උපස්ථිතිවාදයට පාර කැපූ බ්‍රිතාන්‍ය රොමෑන්ටික් ශිල්පියා කවුද?", "ජේ.එම්.ඩබ්ලිව්. ටර්නර්", "පැබ්ලෝ පිකාසෝ", "මයිකල් ආන්ජලෝ", "එඩ්ගා ඩෙගාස්", "ටර්නර්ගේ 'ද ෆයිටින් ටෙමරෙයාර්' හා 'හිම කුණාටුව' සිතුවම් වර්ණ හා ආලෝකයේ විප්ලවයක් විය."),
        q("යුද්ධයේ කෲරත්වය විවේචනය කරමින් '1808 මැයි තුන්වන දා' (The Third of May 1808) ඇඳි ස්පාඤ්ඤ ශිල්පියා කවුද?", "ෆ්‍රැන්සිස්කෝ ගොයා", "කැරවැජියෝ ශිල්පියා", "ජොටෝ ඩි බොන්ඩෝනේ", "ක්ලෝඩ් මොනේ ශිල්පියා", "අසරණ සිවිල් වැසියන් වෙඩි තබා ඝාතනය කරන අවස්ථාව ගොයා ඉතා සංවේදී ලෙස සිතුවම් කළේය."),
        q("19 වන සියවසේ මැද භාගයේදී රජවරුන් හා දේව කතා වෙනුවට සාමාන්‍ය ගොවීන් හා කම්කරුවන්ගේ සැබෑ ජීවිතය සිතුවම් කළ කලා ව්‍යාපාරය කුමක්ද?", "යථාර්ථවාදය (Realism)", "රොකොකෝ කලා ශෛලිය", "විශ්ලේෂණාත්මක ඝනවාදය", "බැරොක් සම්ප්‍රදාය", "'මට දේවදූතයෙකු පෙන්වන්න, මම ඔහුව අඳින්නම්' යැයි කී කෝබේ සාමාන්‍ය සමාජ සත්‍යය ඇන්දේය."),
        q("ගුස්තාව් කෝබේගේ 'ගල් කඩන්නෝ' සහ ජීන්-ෆ්‍රැන්කොයිස් මිලේගේ 'කරල් අහුලන්නියෝ' (The Gleaners) අයත් වන්නේ කුමන චිත්‍ර ශෛලියටද?", "යථාර්ථවාදය (Realism)", "අධියථාර්ථවාදය", "රොමෑන්ටික්වාදය", "පොප් කලාව", "වැඩ කරන පන්තියේ මිනිසුන්ට කලා ඉතිහාසයේ ගෞරවනීය තැනක් යථාර්ථවාදය මගින් හිමි විය."),
        q("සම්භාව්‍ය බටහිර කලාවේ චිත්‍ර හා මූර්ති නිර්මාණයේදී 'කැන්වසය මත තෙල් සායම්' මාධ්‍යය වඩාත් ජනප්‍රිය වීමට ප්‍රධාන හේතුව කුමක්ද?", "සෙමින් වියළී වර්ණ මිශ්‍රණ පහසුව", "තත්පර කිහිපයකින් වියළී යන නිසා", "ජලයේ සේදී පිරිසිදු වන නිසා", "තෙත් බදාම බිත්තිවල පමණක් ඇඳීම", "ෆ්‍රෙස්කෝ හා ටෙම්පරාවලට වඩා තෙල් සායම් ශිල්පියාට දීප්තිමත් වර්ණ ගැඹුරක් ලබා දුන්නේය."),
        q("ග්‍රීක පුරාණ චිත්‍ර කලාව හා මූර්ති කලාව 'රෝමවරුන්ට' මෙන්ම 'පුනරුද යුගයට' ද බලපෑම් කළේ කුමන මූලික පරමාදර්ශය හරහාද?", "මානව සමමිතිය හා ස්වභාවික අනුපාත", "වියුක්ත රේඛා කැපීම හා තිත් රටා", "හැඩතල අසාමාන්‍ය ලෙස විකෘති කිරීම", "පැතලි ද්විමාන වර්ණ පැල්ලම් ගැසීම", "සම්භාව්‍ය ග්‍රීක-රෝම සම්මතයන් (Classical Ideals) සියවස් ගණනාවක් බටහිර කලාවේ පදනම විය.")
    )
}
